-- SELECT: compounds, VALUES, CTEs, joins, windows.
SELECT DISTINCT a, b AS x, c d, t.*, * FROM t;
SELECT 1 UNION SELECT 2 UNION ALL SELECT 3 EXCEPT SELECT 4 INTERSECT SELECT 5;
VALUES (1, 2), (3, 4);
WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM c) SELECT * FROM c;
WITH a AS MATERIALIZED (SELECT 1), b AS NOT MATERIALIZED (SELECT 2) SELECT 1;
SELECT * FROM a, b JOIN c ON a.x = c.x LEFT OUTER JOIN d USING (x) NATURAL FULL JOIN e;
SELECT * FROM (a JOIN b), (SELECT 1) AS s, tvf(1, 2) f, t INDEXED BY i, u NOT INDEXED;
SELECT * FROM t WHERE a GROUP BY b, c HAVING d ORDER BY e ASC NULLS FIRST, f DESC LIMIT 1 OFFSET 2;
SELECT * FROM t LIMIT 1, 2;
SELECT row_number() OVER (), sum(a) OVER w, count(*) FILTER (WHERE a) OVER (PARTITION BY b)
  FROM t WINDOW w AS (base ORDER BY a RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW EXCLUDE TIES),
              v AS (ROWS 3 PRECEDING);
SELECT lead(a) OVER (ORDER BY b GROUPS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING EXCLUDE NO OTHERS) FROM t;
